import XCTest
@testable import ColorComposerCore

/// Replays the committed `color_matching` solver-parity corpus through
/// `WeightedSquaredErrorScorer` and asserts exact agreement with the recorded
/// per-candidate score table, selection, error, and tie-break evidence.
///
/// The corpus is generated by the Elixir server (viamin/color_matching#112,
/// `mix parity.generate`, committed at `priv/parity/v1/corpus.json`) from
/// `ColorMatching.WeightedSquaredError` plus the earliest-wins selection of
/// `ColorMatching.IlluminantMatching`. This app mirrors that solver in
/// `WeightedSquaredErrorScorer`; this suite is the enforcement that the two
/// implementations still agree on selection — including ties, missing-measurement
/// exclusions, and channel weighting. Any failure means the client and server
/// would compose different images from the same palette.
///
/// Corpus expectations are exact `Double` comparisons (no epsilon): every
/// corpus value is a sum of products of exactly-representable binary fractions,
/// so a bit-exact match is reproducible across IEEE 754 implementations and any
/// deviation is real algorithm drift.
///
/// The fixture is loaded relative to this source file so it stays byte-comparable
/// with upstream (see `docs/solver-parity-corpus.md` for refresh instructions).
/// When the package gains declared test resources alongside the generated
/// OpenAPI client migration, switch this to `Bundle.module`.
final class SolverParityCorpusTests: XCTestCase {
    // MARK: - Corpus contract

    /// The corpus stamp this client is written against. When the server bumps
    /// `algorithm_version`, every expectation has moved: refresh the fixture,
    /// re-run, and reconcile any scorer changes in lockstep.
    func testCorpusAlgorithmVersionIsTheOneThisClientMirrors() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, Self.supportedAlgorithmVersion)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
    }

    /// The corpus's light-source keys are exactly this client's canonical
    /// conditions — otherwise channel mapping below would silently drop data.
    func testCorpusLightSourcesMatchClientConditions() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.lightSources, LightingCondition.allCases.map(\.rawValue))
    }

    /// Guards that the corpus actually exercises what it exists to enforce:
    /// exact ties (with recorded tie evidence) and missing-measurement
    /// exclusions, up to and including scenarios with no selection at all.
    func testCorpusCarriesTieAndExclusionEvidence() throws {
        let scenarios = try loadCorpus().scenarios
        XCTAssertTrue(scenarios.contains { $0.expected.tieBroke == true }, "corpus lost its tie scenarios")
        XCTAssertTrue(scenarios.contains { $0.expected.selectedIndex == nil }, "corpus lost its no-selection scenario")
        XCTAssertTrue(
            scenarios.contains { $0.expected.scores.contains { $0.score == .excluded } },
            "corpus lost its exclusion scores"
        )
    }

    // MARK: - Replay

    func testReplayMatchesExpectedSelectionsExactly() throws {
        let corpus = try loadCorpus()
        for scenario in corpus.scenarios {
            let replay = replay(scenario)
            assertMatchesExpected(replay, of: scenario)
        }
    }

    // MARK: - Replay internals

    private static let supportedAlgorithmVersion = 1

    private struct ReplayResult {
        let scores: [Int: ExpectedScore]
        let selectedIndex: Int?
        let selectedError: Double?
        let tiedIndices: [Int]
    }

    /// Scores every palette candidate against the scenario's target using the
    /// scenario's weights, then applies the corpus's earliest-index-wins
    /// selection over the numeric (non-excluded) scores.
    private func replay(_ scenario: ParityCorpus.Scenario) -> ReplayResult {
        let scorer = WeightedSquaredErrorScorer()
        let target = makeTarget(scenario.target)
        let weights = makeWeights(scenario.weights)

        var scores: [Int: ExpectedScore] = [:]
        var best: (index: Int, score: Double)?
        for (index, entry) in scenario.palette.enumerated() {
            let candidate = makeCandidate(entry, at: index)
            switch scorer.score(candidate: candidate, target: target, weights: weights) {
            case .excluded:
                scores[index] = .excluded
            case .score(let value):
                scores[index] = .score(value)
                if best == nil || value < best!.score { best = (index, value) }
            }
        }

        let tied = best.map { bestValue in
            scenario.palette.indices.filter { index in
                guard case .score(let value)? = scores[index] else { return false }
                return value == bestValue.score
            }
        } ?? []
        return ReplayResult(
            scores: scores,
            selectedIndex: best?.index,
            selectedError: best?.score,
            tiedIndices: tied
        )
    }

    private func assertMatchesExpected(_ replay: ReplayResult, of scenario: ParityCorpus.Scenario) {
        let expected = scenario.expected
        XCTAssertEqual(
            replay.scores.count, expected.scores.count,
            "\(scenario.id): candidate count drifted from the corpus"
        )
        assertScoreTable(replay.scores, matches: expected.scores, in: scenario)

        XCTAssertEqual(
            replay.selectedIndex, expected.selectedIndex,
            "\(scenario.id): selected index drifted from the corpus"
        )
        if let selectedIndex = expected.selectedIndex {
            XCTAssertEqual(
                scenario.palette[selectedIndex].hexColor, expected.selectedHexColor,
                "\(scenario.id): selected hex drifted from the corpus"
            )
            XCTAssertEqual(
                replay.selectedError, expected.error,
                "\(scenario.id): selected error drifted from the corpus"
            )
            XCTAssertEqual(
                replay.tiedIndices.count > 1, expected.tieBroke == true,
                "\(scenario.id): tie evidence drifted from the corpus"
            )
        }
        XCTAssertEqual(
            replay.tiedIndices, expected.tiedIndices,
            "\(scenario.id): tied indices drifted from the corpus"
        )
    }

    private func assertScoreTable(
        _ replayed: [Int: ExpectedScore],
        matches expected: [ParityCorpus.Scenario.ScoredEntry],
        in scenario: ParityCorpus.Scenario
    ) {
        for entry in expected {
            switch (replayed[entry.index], entry.score) {
            case (.excluded, .excluded):
                continue
            case (.score(let replayed), .score(let expected)):
                XCTAssertEqual(
                    replayed, expected,
                    "\(scenario.id): score for candidate \(entry.index) drifted from the corpus"
                )
            case let (replayed, expected):
                XCTFail("\(scenario.id): candidate \(entry.index) is \(String(describing: replayed)) but the corpus expects \(expected)")
            }
        }
    }

    /// Unknown light-source keys in the weights map (e.g. `ultraviolet`) are
    /// dropped: `ChannelWeights` only models the canonical conditions, matching
    /// the server's `WeightedSquaredError.filter_weights/1`.
    private func makeWeights(_ raw: [String: Double]) -> ChannelWeights {
        var weights = ChannelWeights()
        for (key, value) in raw {
            switch LightingCondition(rawValue: key) {
            case .white: weights.white = value
            case .red: weights.red = value
            case .green: weights.green = value
            case .blue: weights.blue = value
            case .lps: weights.lps = value
            case nil: continue
            }
        }
        return weights
    }

    /// Absent channel keys mean *missing measurement*, never zero brightness —
    /// exactly the semantics `TargetResponseVector` models.
    private func makeTarget(_ entry: ParityCorpus.Scenario.Entry) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in entry.channels {
            guard let condition = LightingCondition(rawValue: key) else { continue }
            brightness[condition] = value
        }
        return TargetResponseVector(brightness)
    }

    private func makeCandidate(_ entry: ParityCorpus.Scenario.Entry, at index: Int) -> PaletteColor {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in entry.channels {
            guard let condition = LightingCondition(rawValue: key) else { continue }
            responses[condition] = IlluminationResponse(brightness: value)
        }
        return PaletteColor(
            id: index,
            hex: entry.hexColor,
            rgb: RGBColor(hex: entry.hexColor)!,
            responses: responses
        )
    }

    // MARK: - Fixture loading

    private func loadCorpus(file: StaticString = #filePath) throws -> ParityCorpus {
        let fixtureURL = URL(fileURLWithPath: "\(file)", isDirectory: false)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/parity/v1/corpus.json", isDirectory: false)
        let data = try Data(contentsOf: fixtureURL)
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(ParityCorpus.self, from: data)
    }}

// MARK: - Corpus wire model

/// Decoded shape of the committed corpus fixture. Private to the test target;
/// changing the corpus format upstream shows up here first as a decode failure.
private struct ParityCorpus: Codable {
    struct Scenario: Codable {
        struct Entry: Codable {
            let index: Int?
            let hexColor: String
            let channels: [String: Double]
        }

        struct ScoredEntry: Codable {
            let index: Int
            let score: ExpectedScore
        }

        struct Expected: Codable {
            let scores: [ScoredEntry]
            let selectedIndex: Int?
            let selectedHexColor: String?
            let error: Double?
            let tieBroke: Bool?
            let tiedIndices: [Int]
        }

        let id: String
        let description: String
        let weights: [String: Double]
        let target: Entry
        let palette: [Entry]
        let expected: Expected
    }

    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let lightSources: [String]
    let scenarios: [Scenario]
}

/// One recorded candidate outcome: a finite score, or `"excluded"` when the
/// candidate was dropped for missing a positively-weighted measurement.
private enum ExpectedScore: Codable, Equatable {
    case excluded
    case score(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let excluded = try? container.decode(String.self), excluded == "excluded" {
            self = .excluded
        } else {
            self = .score(try container.decode(Double.self))
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .excluded: try container.encode("excluded")
        case .score(let value): try container.encode(value)
        }
    }
}
